      "description": "Uses inventory_has because when an oak_door block is mined/broken, it drops as an oak_door item that goes into the player's inventory. This directly confirms the player broke the door rather than just opening it. The player starts with no oak_door in inventory, so having ≥1 confirms mining occurred.",
      "rules": [
        {
          "type": "inventory_has",
          "params": {
            "item": "oak_door",
            "min_count": 1
          }
        }
      ]
    },
